    /// An array of ProjectArtifact objects. Constraints: o min: 0 o max: 12 (structure) Information about the build output artifacts for the build project. type -&gt; (string) [required] The type of build output artifact. Valid values include: o CODEPIPELINE : The build project has build output generated through CodePipeline. NOTE: The CODEPIPELINE type is not supported for secondaryArti- facts . o NO_ARTIFACTS : The build project does not produce any build output. o S3 : The build project stores build output in Amazon S3. Possible values: o CODEPIPELINE o S3 o NO_ARTIFACTS location -&gt; (string) Information about the build output artifact location: o If type is set to CODEPIPELINE , CodePipeline ignores this value if specified. This is because CodePipeline manages its build output locations instead of CodeBuild. o If type is set to NO_ARTIFACTS , this value is ignored if specified, because no build output is produced. o If type is set to S3 , this is the name of the output bucket. path -&gt; (string) Along with namespaceType and name , the pattern that Code- Build uses to name and store the output artifact: o If type is set to CODEPIPELINE , CodePipeline ignores this value if specified. This is because CodePipeline manages its build output names instead of CodeBuild. o If type is set to NO_ARTIFACTS , this value is ignored if specified, because no build output is produced. o If type is set to S3 , this is the path to the output arti- fact. If path is not specified, path is not used. For example, if path is set to MyArtifacts , namespaceType is set to NONE , and name is set to MyArtifact.zip , the output artifact is stored in the output bucket at MyArti- facts/MyArtifact.zip . namespaceType -&gt; (string) Along with path and name , the pattern that CodeBuild uses to determine the name and location to store the output artifact: o If type is set to CODEPIPELINE , CodePipeline ignores this value if specified. This is because CodePipeline manages its build output names instead of CodeBuild. o If type is set to NO_ARTIFACTS , this value is ignored if specified, because no build output is produced. o If type is set to S3 , valid values include: o BUILD_ID : Include the build ID in the location of the build output artifact. o NONE : Do not include the build ID. This is the default if namespaceType is not specified. For example, if path is set to MyArtifacts , namespaceType is set to BUILD_ID , and name is set to MyArtifact.zip , the output artifact is stored in MyArtifacts/&lt;build-ID&gt;/MyArti- fact.zip . Possible values: o NONE o BUILD_ID name -&gt; (string) Along with path and namespaceType , the pattern that Code- Build uses to name and store the output artifact: o If type is set to CODEPIPELINE , CodePipeline ignores this value if specified. This is because CodePipeline manages its build output names instead of CodeBuild. o If type is set to NO_ARTIFACTS , this value is ignored if specified, because no build output is produced. o If type is set to S3 , this is the name of the output arti- fact object. If you set the name to be a forward slash ("/"), the artifact is stored in the root of the output bucket. For example: o If path is set to MyArtifacts , namespaceType is set to BUILD_ID , and name is set to MyArtifact.zip , then the output artifact is stored in MyArtifacts/&lt;build-ID&gt;/MyArti- fact.zip . o If path is empty, namespaceType is set to NONE , and name is set to "/ ", the output artifact is stored in the root of the output bucket. o If path is set to MyArtifacts , namespaceType is set to BUILD_ID , and name is set to "/ ", the output artifact is stored in MyArtifacts/&lt;build-ID&gt; . packaging -&gt; (string) The type of build output artifact to create: o If type is set to CODEPIPELINE , CodePipeline ignores this value if specified. This is because CodePipeline manages its build output artifacts instead of CodeBuild. o If type is set to NO_ARTIFACTS , this value is ignored if specified, because no build output is produced. o If type is set to S3 , valid values include: o NONE : CodeBuild creates in the output bucket a folder that contains the build output. This is the default if packaging is not specified. o ZIP : CodeBuild creates in the output bucket a ZIP file that contains the build output. Possible values: o NONE o ZIP overrideArtifactName -&gt; (boolean) If this flag is set, a name specified in the buildspec file overrides the artifact name. The name specified in a build- spec file is calculated at build time and uses the Shell Com- mand Language. For example, you can append a date and time to your artifact name so that it is always unique. encryptionDisabled -&gt; (boolean) Set to true if you do not want your output artifacts en- crypted. This option is valid only if your artifacts type is Amazon S3. If this is set with another artifacts type, an in- validInputException is thrown. artifactIdentifier -&gt; (string) An identifier for this artifact definition. bucketOwnerAccess -&gt; (string) Specifies the bucket owner's access for objects that another account uploads to their Amazon S3 bucket. By default, only the account that uploads the objects to the bucket has access to these objects. This property allows you to give the bucket owner access to these objects. NOTE: To use this property, your CodeBuild service role must have the s3:PutBucketAcl permission. This permission al- lows CodeBuild to modify the access control list for the bucket. This property can be one of the following values: NONE The bucket owner does not have access to the objects. This is the default. READ_ONLY The bucket owner has read-only access to the objects. The up- loading account retains ownership of the objects. FULL The bucket owner has full access to the objects. Object own- ership is determined by the following criteria: o If the bucket is configured with the Bucket owner preferred setting, the bucket owner owns the objects. The uploading account will have object access as specified by the bucket's policy. o Otherwise, the uploading account retains ownership of the objects. For more information about Amazon S3 object ownership, see Controlling ownership of uploaded objects using S3 Object Ownership in the Amazon Simple Storage Service User Guide . Possible values: o NONE o READ_ONLY o FULL Shorthand Syntax: type=string,location=string,path=string,namespaceType=string,name=string,packaging=string,overrideArtifactName=boolean,encryptionDisabled=boolean,artifactIdentifier=string,bucketOwnerAccess=string ... JSON Syntax: [ { "type": "CODEPIPELINE"|"S3"|"NO_ARTIFACTS", "location": "string", "path": "string", "namespaceType": "NONE"|"BUILD_ID", "name": "string", "packaging": "NONE"|"ZIP", "overrideArtifactName": true|false, "encryptionDisabled": true|false, "artifactIdentifier": "string", "bucketOwnerAccess": "NONE"|"READ_ONLY"|"FULL" } ... ]
    /// </summary>
    [CliOption("--secondary-artifacts", GroupValues = true)]
    public IEnumerable<string>? SecondaryArtifacts { get; set; }

    /// <summary>
    /// Stores recently used information so that it can be quickly accessed at a later time. type -&gt; (string) [required] The type of cache used by the build project. Valid values in- clude: o NO_CACHE : The build project does not use any cache. o S3 : The build project reads and writes from and to S3. o LOCAL : The build project stores a cache locally on a build host that is only available to that build host. Possible values: o NO_CACHE o S3 o LOCAL location -&gt; (string) Information about the cache location: o NO_CACHE or LOCAL : This value is ignored. o S3 : This is the S3 bucket name/prefix. modes -&gt; (list) An array of strings that specify the local cache modes. You can use one or more local cache modes at the same time. This is only used for LOCAL cache types. Possible values are: LOCAL_SOURCE_CACHE Caches Git metadata for primary and secondary sources. After the cache is created, subsequent builds pull only the change between commits. This mode is a good choice for projects with a clean working directory and a source that is a large Git repository. If you choose this option and your project does not use a Git repository (GitHub, GitHub Enterprise, or Bitbucket), the option is ignored. LOCAL_DOCKER_LAYER_CACHE Caches existing Docker layers. This mode is a good choice for projects that build or pull large Docker images. It can prevent the performance issues caused by pulling large Docker images down from the network. NOTE: o You can use a Docker layer cache in the Linux environment only. o The privileged flag must be set so that your project has the required Docker permissions. o You should consider the security implications before you use a Docker layer cache. LOCAL_CUSTOM_CACHE Caches directories you specify in the buildspec file. This mode is a good choice if your build scenario is not suited to one of the other three local cache modes. If you use a custom cache: o Only directories can be specified for caching. You cannot specify individual files. o Symlinks are used to reference cached directories. o Cached directories are linked to your build before it down- loads its project sources. Cached items are overridden if a source item has the same name. Directories are specified using cache paths in the buildspec file. (string) Possible values: o LOCAL_DOCKER_LAYER_CACHE o LOCAL_SOURCE_CACHE o LOCAL_CUSTOM_CACHE cacheNamespace -&gt; (string) Defines the scope of the cache. You can use this namespace to share a cache across multiple projects. For more information, see Cache sharing between projects in the CodeBuild User Guide . Shorthand Syntax: type=string,location=string,modes=string,string,cacheNamespace=string JSON Syntax: { "type": "NO_CACHE"|"S3"|"LOCAL", "location": "string", "modes": ["LOCAL_DOCKER_LAYER_CACHE"|"LOCAL_SOURCE_CACHE"|"LOCAL_CUSTOM_CACHE", ...], "cacheNamespace": "string" }
    /// </summary>
    [CliOption("--cache")]
    public string? Cache { get; set; }

    /// <summary>
    /// Information to be changed about the build environment for the build project. type -&gt; (string) [required] The type of build environment to use for related builds. NOTE: If you're using compute fleets during project creation, type will be ignored. For more information, see Build environment compute types in the CodeBuild user guide . Possible values: o WINDOWS_CONTAINER o LINUX_CONTAINER o LINUX_GPU_CONTAINER o ARM_CONTAINER o WINDOWS_SERVER_2019_CONTAINER o WINDOWS_SERVER_2022_CONTAINER o LINUX_LAMBDA_CONTAINER o ARM_LAMBDA_CONTAINER o LINUX_EC2 o ARM_EC2 o WINDOWS_EC2 o MAC_ARM image -&gt; (string) [required] The image tag or image digest that identifies the Docker image to use for this build project. Use the following formats: o For an image tag: &lt;registry&gt;/&lt;repository&gt;:&lt;tag&gt; . For example, in the Docker repository that CodeBuild uses to manage its Docker images, this would be aws/codebuild/standard:4.0 . o For an image digest: &lt;registry&gt;/&lt;repository&gt;@&lt;digest&gt; . For example, to specify an image with the digest "sha256:cbbf2f9a99b47fc460d422812b6a5adff7dfee951d8fa2e4a98caa0382cf- bdbf," use &lt;registry&gt;/&lt;reposi- tory&gt;@sha256:cbbf2f9a99b47fc460d422812b6a5adff7dfee951d8fa2e4a98caa0382cf- bdbf . For more information, see Docker images provided by CodeBuild in the CodeBuild user guide . Constraints: o min: 1 computeType -&gt; (string) [required] Information about the compute resources the build project uses. Available values include: o ATTRIBUTE_BASED_COMPUTE : Specify the amount of vCPUs, memory, disk space, and the type of machine. NOTE: If you use ATTRIBUTE_BASED_COMPUTE , you must define your at- tributes by using computeConfiguration . CodeBuild will se- lect the cheapest instance that satisfies your specified at- tributes. For more information, see Reserved capacity envi- ronment types in the CodeBuild User Guide . o BUILD_GENERAL1_SMALL : Use up to 4 GiB memory and 2 vCPUs for builds. o BUILD_GENERAL1_MEDIUM : Use up to 8 GiB memory and 4 vCPUs for builds. o BUILD_GENERAL1_LARGE : Use up to 16 GiB memory and 8 vCPUs for builds, depending on your environment type. o BUILD_GENERAL1_XLARGE : Use up to 72 GiB memory and 36 vCPUs for builds, depending on your environment type. o BUILD_GENERAL1_2XLARGE : Use up to 144 GiB memory, 72 vCPUs, and 824 GB of SSD storage for builds. This compute type sup- ports Docker images up to 100 GB uncompressed. o BUILD_LAMBDA_1GB : Use up to 1 GiB memory for builds. Only available for environment type LINUX_LAMBDA_CONTAINER and ARM_LAMBDA_CONTAINER . o BUILD_LAMBDA_2GB : Use up to 2 GiB memory for builds. Only available for environment type LINUX_LAMBDA_CONTAINER and ARM_LAMBDA_CONTAINER . o BUILD_LAMBDA_4GB : Use up to 4 GiB memory for builds. Only available for environment type LINUX_LAMBDA_CONTAINER and ARM_LAMBDA_CONTAINER . o BUILD_LAMBDA_8GB : Use up to 8 GiB memory for builds. Only available for environment type LINUX_LAMBDA_CONTAINER and ARM_LAMBDA_CONTAINER . o BUILD_LAMBDA_10GB : Use up to 10 GiB memory for builds. Only available for environment type LINUX_LAMBDA_CONTAINER and ARM_LAMBDA_CONTAINER . If you use BUILD_GENERAL1_SMALL : o For environment type LINUX_CONTAINER , you can use up to 4 GiB memory and 2 vCPUs for builds. o For environment type LINUX_GPU_CONTAINER , you can use up to 16 GiB memory, 4 vCPUs, and 1 NVIDIA A10G Tensor Core GPU for builds. o For environment type ARM_CONTAINER , you can use up to 4 GiB memory and 2 vCPUs on ARM-based processors for builds. If you use BUILD_GENERAL1_LARGE : o For environment type LINUX_CONTAINER , you can use up to 16 GiB memory and 8 vCPUs for builds. o For environment type LINUX_GPU_CONTAINER , you can use up to 255 GiB memory, 32 vCPUs, and 4 NVIDIA Tesla V100 GPUs for builds. o For environment type ARM_CONTAINER , you can use up to 16 GiB memory and 8 vCPUs on ARM-based processors for builds. For more information, see On-demand environment types in the CodeBuild User Guide. Possible values: o BUILD_GENERAL1_SMALL o BUILD_GENERAL1_MEDIUM o BUILD_GENERAL1_LARGE o BUILD_GENERAL1_XLARGE o BUILD_GENERAL1_2XLARGE o BUILD_LAMBDA_1GB o BUILD_LAMBDA_2GB o BUILD_LAMBDA_4GB o BUILD_LAMBDA_8GB o BUILD_LAMBDA_10GB o ATTRIBUTE_BASED_COMPUTE o CUSTOM_INSTANCE_TYPE computeConfiguration -&gt; (structure) The compute configuration of the build project. This is only re- quired if computeType is set to ATTRIBUTE_BASED_COMPUTE . vCpu -&gt; (long) The number of vCPUs of the instance type included in your fleet. memory -&gt; (long) The amount of memory of the instance type included in your fleet. disk -&gt; (long) The amount of disk space of the instance type included in your fleet. machineType -&gt; (string) The machine type of the instance type included in your fleet. Possible values: o GENERAL o NVME instanceType -&gt; (string) The EC2 instance type to be launched in your fleet. Constraints: o min: 1 fleet -&gt; (structure) A ProjectFleet object to use for this build project. fleetArn -&gt; (string) Specifies the compute fleet ARN for the build project. environmentVariables -&gt; (list) A set of environment variables to make available to builds for this build project. (structure) Information about an environment variable for a build project or a build. name -&gt; (string) [required] The name or key of the environment variable. Constraints: o min: 1 value -&gt; (string) [required] The value of the environment variable. WARNING: We strongly discourage the use of PLAINTEXT environ- ment variables to store sensitive values, especially Amazon Web Services secret key IDs. PLAINTEXT environ- ment variables can be displayed in plain text using the CodeBuild console and the CLI. For sensitive val- ues, we recommend you use an environment variable of type PARAMETER_STORE or SECRETS_MANAGER . type -&gt; (string) The type of environment variable. Valid values include: o PARAMETER_STORE : An environment variable stored in Systems Manager Parameter Store. For environment vari- ables of this type, specify the name of the parameter as the value of the EnvironmentVariable. The parameter value will be substituted for the name at runtime. You can also define Parameter Store environment variables in the buildspec. To learn how to do so, see env/parameter-store in the CodeBuild User Guide . o PLAINTEXT : An environment variable in plain text for- mat. This is the default value. o SECRETS_MANAGER : An environment variable stored in Se- crets Manager. For environment variables of this type, specify the name of the secret as the value of the En- vironmentVariable. The secret value will be substituted for the name at runtime. You can also define Secrets Manager environment variables in the buildspec. To learn how to do so, see env/secrets-manager in the CodeBuild User Guide . Possible values: o PLAINTEXT o PARAMETER_STORE o SECRETS_MANAGER privilegedMode -&gt; (boolean) Enables running the Docker daemon inside a Docker container. Set to true only if the build project is used to build Docker im- ages. Otherwise, a build that attempts to interact with the Docker daemon fails. The default setting is false . You can initialize the Docker daemon during the install phase of your build by adding one of the following sets of commands to the install phase of your buildspec file: If the operating system's base image is Ubuntu Linux: - nohup /usr/local/bin/dockerd --host=unix:///var/run/docker.sock --host=tcp://0.0.0.0:2375 --storage-driver=overlay&amp; - timeout 15 sh -c "until docker info; do echo .; sleep 1; done" If the operating system's base image is Alpine Linux and the previous command does not work, add the -t argument to timeout : - nohup /usr/local/bin/dockerd --host=unix:///var/run/docker.sock --host=tcp://0.0.0.0:2375 --storage-driver=overlay&amp; - timeout -t 15 sh -c "until docker info; do echo .; sleep 1; done" certificate -&gt; (string) The ARN of the Amazon S3 bucket, path prefix, and object key that contains the PEM-encoded certificate for the build project. For more information, see certificate in the CodeBuild User Guide . registryCredential -&gt; (structure) The credentials for access to a private registry. credential -&gt; (string) [required] The Amazon Resource Name (ARN) or name of credentials created using Secrets Manager. NOTE: The credential can use the name of the credentials only if they exist in your current Amazon Web Services Region. Constraints: o min: 1 credentialProvider -&gt; (string) [required] The service that created the credentials to access a private Docker registry. The valid value, SECRETS_MANAGER, is for Se- crets Manager. Possible values: o SECRETS_MANAGER imagePullCredentialsType -&gt; (string) The type of credentials CodeBuild uses to pull images in your build. There are two valid values: o CODEBUILD specifies that CodeBuild uses its own credentials. This requires that you modify your ECR repository policy to trust CodeBuild service principal. o SERVICE_ROLE specifies that CodeBuild uses your build project's service role. When you use a cross-account or private registry image, you must use SERVICE_ROLE credentials. When you use an CodeBuild curated image, you must use CODEBUILD credentials. Possible values: o CODEBUILD o SERVICE_ROLE dockerServer -&gt; (structure) A DockerServer object to use for this build project. computeType -&gt; (string) [required] Information about the compute resources the docker server uses. Available values include: o BUILD_GENERAL1_SMALL : Use up to 4 GiB memory and 2 vCPUs for your docker server. o BUILD_GENERAL1_MEDIUM : Use up to 8 GiB memory and 4 vCPUs for your docker server. o BUILD_GENERAL1_LARGE : Use up to 16 GiB memory and 8 vCPUs for your docker server. o BUILD_GENERAL1_XLARGE : Use up to 64 GiB memory and 32 vC- PUs for your docker server. o BUILD_GENERAL1_2XLARGE : Use up to 128 GiB memory and 64 vCPUs for your docker server. Possible values: o BUILD_GENERAL1_SMALL o BUILD_GENERAL1_MEDIUM o BUILD_GENERAL1_LARGE o BUILD_GENERAL1_XLARGE o BUILD_GENERAL1_2XLARGE o BUILD_LAMBDA_1GB o BUILD_LAMBDA_2GB o BUILD_LAMBDA_4GB o BUILD_LAMBDA_8GB o BUILD_LAMBDA_10GB o ATTRIBUTE_BASED_COMPUTE o CUSTOM_INSTANCE_TYPE securityGroupIds -&gt; (list) A list of one or more security groups IDs. NOTE: Security groups configured for Docker servers should al- low ingress network traffic from the VPC configured in the project. They should allow ingress on port 9876. Constraints: o max: 5 (string) Constraints: o min: 1 status -&gt; (structure) A DockerServerStatus object to use for this docker server. NOTE: Note that status is only an output and cannot be passed in as an input. status -&gt; (string) The status of the docker server. message -&gt; (string) A message associated with the status of a docker server. hostKernel -&gt; (string) The host operating system kernel used for on-demand builds in the build project. The host kernel does not affect the build en- vironment operating system, which is determined by the image you specify. Valid values are: o LINUX_KERNEL_4 : Runs on an Amazon Linux 2 host (kernel 4.x). o LINUX_KERNEL_6 : Runs on an Amazon Linux 2023 host (kernel 6.x). o LINUX_KERNEL_LATEST : Runs on the latest supported host ker- nel. This setting applies to the LINUX_CONTAINER , ARM_CONTAINER , LINUX_EC2 , and ARM_EC2 environment types. It is not applicable to Windows, Lambda, or Mac environment types. Possible values: o LINUX_KERNEL_4 o LINUX_KERNEL_6 o LINUX_KERNEL_LATEST Shorthand Syntax: type=string,image=string,computeType=string,computeConfiguration={vCpu=long,memory=long,disk=long,machineType=string,instanceType=string},fleet={fleetArn=string},environmentVariables=[{name=string,value=string,type=string},{name=string,value=string,type=string}],privilegedMode=boolean,certificate=string,registryCredential={credential=string,credentialProvider=string},imagePullCredentialsType=string,dockerServer={computeType=string,securityGroupIds=[string,string],status={status=string,message=string}},hostKernel=string JSON Syntax: { "type": "WINDOWS_CONTAINER"|"LINUX_CONTAINER"|"LINUX_GPU_CONTAINER"|"ARM_CONTAINER"|"WINDOWS_SERVER_2019_CONTAINER"|"WINDOWS_SERVER_2022_CONTAINER"|"LINUX_LAMBDA_CONTAINER"|"ARM_LAMBDA_CONTAINER"|"LINUX_EC2"|"ARM_EC2"|"WINDOWS_EC2"|"MAC_ARM", "image": "string", "computeType": "BUILD_GENERAL1_SMALL"|"BUILD_GENERAL1_MEDIUM"|"BUILD_GENERAL1_LARGE"|"BUILD_GENERAL1_XLARGE"|"BUILD_GENERAL1_2XLARGE"|"BUILD_LAMBDA_1GB"|"BUILD_LAMBDA_2GB"|"BUILD_LAMBDA_4GB"|"BUILD_LAMBDA_8GB"|"BUILD_LAMBDA_10GB"|"ATTRIBUTE_BASED_COMPUTE"|"CUSTOM_INSTANCE_TYPE", "computeConfiguration": { "vCpu": long, "memory": long, "disk": long, "machineType": "GENERAL"|"NVME", "instanceType": "string" }, "fleet": { "fleetArn": "string" }, "environmentVariables": [ { "name": "string", "value": "string", "type": "PLAINTEXT"|"PARAMETER_STORE"|"SECRETS_MANAGER" } ... ], "privilegedMode": true|false, "certificate": "string", "registryCredential": { "credential": "string", "credentialProvider": "SECRETS_MANAGER" }, "imagePullCredentialsType": "CODEBUILD"|"SERVICE_ROLE", "dockerServer": { "computeType": "BUILD_GENERAL1_SMALL"|"BUILD_GENERAL1_MEDIUM"|"BUILD_GENERAL1_LARGE"|"BUILD_GENERAL1_XLARGE"|"BUILD_GENERAL1_2XLARGE"|"BUILD_LAMBDA_1GB"|"BUILD_LAMBDA_2GB"|"BUILD_LAMBDA_4GB"|"BUILD_LAMBDA_8GB"|"BUILD_LAMBDA_10GB"|"ATTRIBUTE_BASED_COMPUTE"|"CUSTOM_INSTANCE_TYPE", "securityGroupIds": ["string", ...], "status": { "status": "string", "message": "string" } }, "hostKernel": "LINUX_KERNEL_4"|"LINUX_KERNEL_6"|"LINUX_KERNEL_LATEST" }
    /// </summary>
    [SecretValue]
    [CliOption("--environment")]
    public string? Environment { get; set; }

    /// <summary>
    /// The replacement ARN of the IAM role that enables CodeBuild to inter- act with dependent Amazon Web Services services on behalf of the Amazon Web Services account. Constraints: o min: 1
    /// </summary>
    [CliOption("--service-role")]
    public string? ServiceRole { get; set; }

    /// <summary>
    /// The replacement value in minutes, from 5 to 2160 (36 hours), for CodeBuild to wait before timing out any related build that did not get marked as completed. Constraints: o min: 5 o max: 2160
    /// </summary>
    [CliOption("--timeout-in-minutes")]
    public int? TimeoutInMinutes { get; set; }

    /// <summary>
    /// The number of minutes a build is allowed to be queued before it times out. Constraints: o min: 5 o max: 480
    /// </summary>
    [CliOption("--queued-timeout-in-minutes")]
    public int? QueuedTimeoutInMinutes { get; set; }

    /// <summary>
    /// The Key Management Service customer master key (CMK) to be used for encrypting the build output artifacts. NOTE: You can use a cross-account KMS key to encrypt the build output artifacts if your service role has permission to that key. You can specify either the Amazon Resource Name (ARN) of the CMK or, if available, the CMK's alias (using the format alias/&lt;alias-name&gt; ). Constraints: o min: 1
    /// </summary>
    [CliOption("--encryption-key")]
    public string? EncryptionKey { get; set; }

    /// <summary>
    /// An updated list of tag key and value pairs associated with this build project. These tags are available for use by Amazon Web Services services that support CodeBuild build project tags. Constraints: o min: 0 o max: 50 (structure) A tag, consisting of a key and a value. This tag is available for use by Amazon Web Services services that support tags in CodeBuild. key -&gt; (string) The tag's key. Constraints: o min: 1 o max: 127 o pattern: ^([\p{L}\p{Z}\p{N}_.:/=@+\-]*)$ value -&gt; (string) The tag's value. Constraints: o min: 0 o max: 255 o pattern: ^([\p{L}\p{Z}\p{N}_.:/=@+\-]*)$ Shorthand Syntax: key=string,value=string ... JSON Syntax: [ { "key": "string", "value": "string" } ... ]
    /// </summary>
    [CliOption("--tags", GroupValues = true)]
    public IEnumerable<string>? Tags { get; set; }

    /// <summary>
    /// VpcConfig enables CodeBuild to access resources in an Amazon VPC. vpcId -&gt; (string) The ID of the Amazon VPC. Constraints: o min: 1 subnets -&gt; (list) A list of one or more subnet IDs in your Amazon VPC. Constraints: o max: 16 (string) Constraints: o min: 1 securityGroupIds -&gt; (list) A list of one or more security groups IDs in your Amazon VPC. Constraints: o max: 5 (string) Constraints: o min: 1 Shorthand Syntax: vpcId=string,subnets=string,string,securityGroupIds=string,string JSON Syntax: { "vpcId": "string", "subnets": ["string", ...], "securityGroupIds": ["string", ...] }
    /// </summary>
    [CliOption("--vpc-config")]
    public string? VpcConfig { get; set; }

    /// <summary>
    /// Set this to true to generate a publicly accessible URL for your project's build badge.
    /// </summary>
    [CliFlag("--badge-enabled", NegatedName = "--no-badge-enabled")]
    public bool? BadgeEnabled { get; set; }

    /// <summary>
    /// Information about logs for the build project. A project can create logs in CloudWatch Logs, logs in an S3 bucket, or both. cloudWatchLogs -&gt; (structure) Information about CloudWatch Logs for a build project. Cloud- Watch Logs are enabled by default. status -&gt; (string) [required] The current status of the logs in CloudWatch Logs for a build project. Valid values are: o ENABLED : CloudWatch Logs are enabled for this build project. o DISABLED : CloudWatch Logs are not enabled for this build project. Possible values: o ENABLED o DISABLED groupName -&gt; (string) The group name of the logs in CloudWatch Logs. For more in- formation, see Working with Log Groups and Log Streams . streamName -&gt; (string) The prefix of the stream name of the CloudWatch Logs. For more information, see Working with Log Groups and Log Streams . s3Logs -&gt; (structure) Information about logs built to an S3 bucket for a build project. S3 logs are not enabled by default. status -&gt; (string) [required] The current status of the S3 build logs. Valid values are: o ENABLED : S3 build logs are enabled for this build project. o DISABLED : S3 build logs are not enabled for this build project. Possible values: o ENABLED o DISABLED location -&gt; (string) The ARN of an S3 bucket and the path prefix for S3 logs. If your Amazon S3 bucket name is my-bucket , and your path pre- fix is build-log , then acceptable formats are my-bucket/build-log or arn:aws:s3:::my-bucket/build-log . encryptionDisabled -&gt; (boolean) Set to true if you do not want your S3 build log output en- crypted. By default S3 build logs are encrypted. bucketOwnerAccess -&gt; (string) Specifies the bucket owner's access for objects that another account uploads to their Amazon S3 bucket. By default, only the account that uploads the objects to the bucket has access to these objects. This property allows you to give the bucket owner access to these objects. NOTE: To use this property, your CodeBuild service role must have the s3:PutBucketAcl permission. This permission al- lows CodeBuild to modify the access control list for the bucket. This property can be one of the following values: NONE The bucket owner does not have access to the objects. This is the default. READ_ONLY The bucket owner has read-only access to the objects. The up- loading account retains ownership of the objects. FULL The bucket owner has full access to the objects. Object own- ership is determined by the following criteria: o If the bucket is configured with the Bucket owner preferred setting, the bucket owner owns the objects. The uploading account will have object access as specified by the bucket's policy. o Otherwise, the uploading account retains ownership of the objects. For more information about Amazon S3 object ownership, see Controlling ownership of uploaded objects using S3 Object Ownership in the Amazon Simple Storage Service User Guide . Possible values: o NONE o READ_ONLY o FULL Shorthand Syntax: cloudWatchLogs={status=string,groupName=string,streamName=string},s3Logs={status=string,location=string,encryptionDisabled=boolean,bucketOwnerAccess=string} JSON Syntax: { "cloudWatchLogs": { "status": "ENABLED"|"DISABLED", "groupName": "string", "streamName": "string" }, "s3Logs": { "status": "ENABLED"|"DISABLED", "location": "string", "encryptionDisabled": true|false, "bucketOwnerAccess": "NONE"|"READ_ONLY"|"FULL" } }
    /// </summary>
    [CliOption("--logs-config")]
    public string? LogsConfig { get; set; }

    /// <summary>
    /// An array of ProjectFileSystemLocation objects for a CodeBuild build project. A ProjectFileSystemLocation object specifies the identifier , location , mountOptions , mountPoint , and type of a file system created using Amazon Elastic File System. (structure) Information about a file system created by Amazon Elastic File System (EFS). For more information, see What Is Amazon Elastic File System? type -&gt; (string) The type of the file system. The one supported type is EFS . Possible values: o EFS location -&gt; (string) A string that specifies the location of the file system cre- ated by Amazon EFS. Its format is efs-dns-name:/direc- tory-path . You can find the DNS name of file system when you view it in the Amazon EFS console. The directory path is a path to a directory in the file system that CodeBuild mounts. For example, if the DNS name of a file system is fs-abcd1234.efs.us-west-2.amazonaws.com , and its mount di- rectory is my-efs-mount-directory , then the location is fs-abcd1234.efs.us-west-2.amazonaws.com:/my-efs-mount-direc- tory . The directory path in the format efs-dns-name:/directory-path is optional. If you do not specify a directory path, the lo- cation is only the DNS name and CodeBuild mounts the entire file system. mountPoint -&gt; (string) The location in the container where you mount the file sys- tem. identifier -&gt; (string) The name used to access a file system created by Amazon EFS. CodeBuild creates an environment variable by appending the identifier in all capital letters to CODEBUILD_ . For exam- ple, if you specify my_efs for identifier , a new environment variable is create named CODEBUILD_MY_EFS . The identifier is used to mount your file system. mountOptions -&gt; (string) The mount options for a file system created by Amazon EFS. The default mount options used by CodeBuild are nfsvers=4.1,rsize=1048576,wsize=1048576,hard,timeo=600,re- trans=2 . For more information, see Recommended NFS Mount Op- tions . Shorthand Syntax: type=string,location=string,mountPoint=string,identifier=string,mountOptions=string ... JSON Syntax: [ { "type": "EFS", "location": "string", "mountPoint": "string", "identifier": "string", "mountOptions": "string" } ... ]
    /// </summary>
    [CliOption("--file-system-locations", GroupValues = true)]
    public IEnumerable<string>? FileSystemLocations { get; set; }

    /// <summary>
    /// Contains configuration information about a batch build project. serviceRole -&gt; (string) Specifies the service role ARN for the batch build project. Constraints: o min: 1 combineArtifacts -&gt; (boolean) Specifies if the build artifacts for the batch build should be combined into a single artifact location. restrictions -&gt; (structure) A BatchRestrictions object that specifies the restrictions for the batch build. maximumBuildsAllowed -&gt; (integer) Specifies the maximum number of builds allowed. computeTypesAllowed -&gt; (list) An array of strings that specify the compute types that are allowed for the batch build. See Build environment compute types in the CodeBuild User Guide for these values. (string) Constraints: o min: 1 fleetsAllowed -&gt; (list) An array of strings that specify the fleets that are allowed for the batch build. See Run builds on reserved capacity fleets in the CodeBuild User Guide for more information. (string) Constraints: o min: 1 timeoutInMins -&gt; (integer) Specifies the maximum amount of time, in minutes, that the batch build must be completed in. batchReportMode -&gt; (string) Specifies how build status reports are sent to the source provider for the batch build. This property is only used when the source provider for your project is Bitbucket, GitHub, or GitHub Enterprise, and your project is configured to report build statuses to the source provider. REPORT_AGGREGATED_BATCH (Default) Aggregate all of the build statuses into a single sta- tus report. REPORT_INDIVIDUAL_BUILDS Send a separate status report for each individual build. Possible values: o REPORT_INDIVIDUAL_BUILDS o REPORT_AGGREGATED_BATCH Shorthand Syntax: serviceRole=string,combineArtifacts=boolean,restrictions={maximumBuildsAllowed=integer,computeTypesAllowed=[string,string],fleetsAllowed=[string,string]},timeoutInMins=integer,batchReportMode=string JSON Syntax: { "serviceRole": "string", "combineArtifacts": true|false, "restrictions": { "maximumBuildsAllowed": integer, "computeTypesAllowed": ["string", ...], "fleetsAllowed": ["string", ...] }, "timeoutInMins": integer, "batchReportMode": "REPORT_INDIVIDUAL_BUILDS"|"REPORT_AGGREGATED_BATCH" }
    /// </summary>
    [CliOption("--build-batch-config")]
    public string? BuildBatchConfig { get; set; }

    /// <summary>
    /// The maximum number of concurrent builds that are allowed for this project. New builds are only started if the current number of builds is less than or equal to this limit. If the current build count meets this limit, new builds are throttled and are not run. To remove this limit, set this value to -1.
    /// </summary>
    [CliOption("--concurrent-build-limit")]
    public int? ConcurrentBuildLimit { get; set; }

    /// <summary>
    /// The maximum number of additional automatic retries after a failed build. For example, if the auto-retry limit is set to 2, CodeBuild will call the RetryBuild API to automatically retry your build for up to 2 additional times.
    /// </summary>
    [CliOption("--auto-retry-limit")]
    public int? AutoRetryLimit { get; set; }

    [CliOption("--cli-input-json")]
    public string? CliInputJson { get; set; }

    [CliOption("--generate-cli-skeleton")]
    public string? GenerateCliSkeleton { get; set; }

    /// <inheritdoc />
    IEnumerable<ValidationResult> IValidatableObject.Validate(ValidationContext validationContext)
    {
        if (_requiresAlternateInput && !(!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input"))
        {
            yield return new ValidationResult("An alternate input must remain selected for an instance created without required operation values.");
            yield break;
        }

        if (!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input")
        {
            yield break;
        }

    }

}
